from lib import *
S = SS('t10')
steps = [
    step("脏读。Saga 第一步把账户扣掉 800(已经提交),第二步失败、100 ms 后补偿加回 800;一个“额度审批”服务每 5 ms 读一次余额,规则是余额 >= 500 才批准贷款。30 个 saga 依次跑完共 6.3 秒,审批服务读了 1007 次,读到过的余额值是 200 和 1000。读到中间状态 200 并因此拒绝贷款的有 506 次(50%)——这些拒绝全是错的:每个 saga 最后都被补偿了,账户余额从来没有真的低于 1000。Saga 的每一步都是已提交的本地事务,中间状态对所有人可见。", t=tl(S(1)), mark=lidx(S(1), '读到中间状态 200'), done=lidx(S(1), '最终余额'), b=bars([['审批读到的次数', 1007, '1007'], ['其中读到 200 而错误拒绝', 506, '506']], 1007, cur=[0], mark=[1]), kv=KV([['Saga 步骤', '每一步都已提交,别人读得到'], ['审批服务', '506 / 1007 次基于中间状态拒绝'], ['真实余额', '从未低于 1000']], ['审批服务'])),
    step("补偿覆盖别人的更新。Saga 扣款 100 后需要补偿,同时另一个事务给账户加了 5 元利息(落在随机时刻),正确终态是 1005。写法 A:补偿“把余额恢复成扣款之前读到的值”:200 次里有 90 次终态不是 1005(45%),利息被覆盖掉了(丢失更新)。写法 B:补偿“把扣掉的 100 加回去”(相对增量):200 次里 0 次。利息落在“扣款之后、补偿之前”这个窗口里时,绝对值补偿会抹掉它;相对增量不关心先后顺序。", t=tl(S(2)), mark=lidx(S(2), '写法 A'), done=lidx(S(2), '写法 B'), b=bars([['写法 A 丢了利息的次数', 90, '90 / 200'], ['写法 B 丢了利息的次数', 0, '0 / 200']], 200, mark=[0], done=[1]), kv=KV([['绝对值补偿', '覆盖并发更新,丢 45%'], ['相对增量补偿', '不受先后顺序影响'], ['原则', '补偿尽量写成可交换的增量']], ['原则'])),
    step("中间状态让别人买不到。库存只剩 1 件,saga 在 0.1 秒预留这 1 件、0.3 秒时因支付失败释放;60 个买家在 0 到 0.4 秒之间随机到达。买家被拒绝(库存不足)27 次,全部落在预留窗口里,窗口里到达的买家共 27 个;晚于 0.3 秒到的买家买到了。窗口里被拒的买家,本来在补偿之后是卖得出去的——丢了单。这是“预留 / 冻结可见”的代价,TCC 里也一样(第 6 篇)。", t=tl(S(3)), mark=lidx(S(3), '买家被拒绝(库存不足)'), done=lidx(S(3), '被拒绝的买家全部落在预留窗口里'), b=bars([['窗口里到达的买家', 27, '27'], ['其中被拒绝', 27, '27']], 30, cur=[0], mark=[1]), kv=KV([['预留窗口', '0.1 s ~ 0.3 s'], ['窗口里到达', '27 个买家全被拒'], ['0.3 s 之后', '补偿完成,买得到']], ['预留窗口'])),
    step("对策:语义锁。把“正在被 saga 处理”的金额写进 pending 列:扣款时 balance -= 800、pending += 800;补偿时 balance += 800、pending -= 800;读者判断总资产时用 balance + pending。同样的 30 个 saga:审批服务读了 1006 次,其中 505 次读到了 saga 进行中的状态(pending > 0),错误拒绝 0 次。另一类“等待型”读者看到 pending > 0 就等到 saga 收尾再决定:等了 30 次,每次平均 102 ms、最长 106 ms,换来的是永远只看到已收尾的状态。读者要主动理解 pending,这是对策的代价。", t=tl(S(4)), mark=lidx(S(4), '错误拒绝 0 次'), done=lidx(S(4), '“等待型”读者'), b=bars([['读到 saga 进行中状态的次数', 505, '505'], ['其中错误拒绝', 0, '0'], ['等待型读者平均等待 ms', 102, '102']], 520, cur=[0], done=[1], mark=[2]), kv=KV([['balance + pending', '505 次中间状态,0 次误判'], ['等待型读者', '平均等 102 ms,看到的都是收尾后的状态'], ['代价', '读者要理解 pending']], ['代价'])),
    step("三种做法放在一起。无防护(读 balance、绝对值补偿):审批被错误拒绝 506 次,丢失的更新 90 次。只改补偿、用相对增量:错误拒绝仍是 506 次(读者还是读到了中间状态),丢失的更新降到 0。相对增量加语义锁(pending 列):错误拒绝 0、丢失的更新 0。Saga 没有隔离性,要靠这些应用层的办法逐个补回来;每一种办法都是对具体读写的约束,没有一个通用的开关。", t=tl(S(5)), mark=lidx(S(5), '无防护'), done=lidx(S(5), '相对增量 + 语义锁'), b=bars([['无防护:错误拒绝', 506, '506'], ['相对增量:错误拒绝', 506, '506'], ['语义锁:错误拒绝', 0, '0'], ['无防护:丢失更新', 90, '90']], 520, mark=[0, 1, 3], done=[2]), kv=KV([['相对增量', '解决丢失更新(90 → 0)'], ['语义锁', '解决脏读误判(506 → 0)'], ['没有通用办法', '每种读写要单独设计']], ['没有通用办法'])),
]
A = mkartt('t10', 10, '分布式事务,Saga,隔离性,脏读,丢失更新,语义锁,MySQL,真实验证,动画演示',
    '实测 Saga 没有隔离性的后果:中间状态被别人读到(1007 次读里 506 次错误拒绝)、绝对值补偿覆盖并发更新(200 次里丢 90 次)、预留窗口里到达的 27 个买家全被拒;相对增量补偿把丢失更新降到 0,语义锁(pending 列)把错误拒绝降到 0。',
    'Saga 的每一步都是已经提交的本地事务,所以别的事务能读到它的中间状态,补偿也可能和别人的更新交错。这篇把脏读、补偿覆盖并发更新、中间状态造成的丢单三种异常逐个复现,再试语义锁和相对增量两种对策。',
    [('506 / 1007', '审批服务读到 Saga 的中间状态而错误拒绝贷款的次数 / 总读取次数'), ('90 / 200', '补偿“恢复成扣款前的值”时,覆盖掉并发利息更新的次数(相对增量是 0)'), ('27 / 27', '库存预留窗口里到达的买家全部被拒(窗口外的都买到了)')],
    [('脏读', '<p>每一步都已提交,中间状态对所有人可见。审批服务一半的读取看到被扣掉的 800,于是拒绝了本来能批准的贷款。</p>'),
     ('补偿覆盖别人的更新', '<p>补偿写“恢复成旧值”会抹掉扣款与补偿之间别人写入的更新;写“加回扣掉的数”则与别的更新可交换。</p>'),
     ('中间状态造成丢单', '<p>库存被预留的那段时间,买家被拒;预留释放后这些单本可成交。</p>'),
     ('语义锁', '<p>在 pending 列里标出“正在被 saga 处理”的量,读者用 balance + pending 判断总资产就不被中间状态误导;等待型读者则等到 saga 收尾。代价是读者要理解 pending。</p>'),
     ('对策对比', '<p>相对增量解决丢失更新,语义锁解决脏读误判,两者各管一类。没有通用开关。</p>')],
    steps,
    [ENV_T + '。本篇用一个 MySQL 26.7.0 实例的 bank 库,Saga 的每个步骤是 autocommit 的单条语句,窗口用真实 sleep(100 ms / 20 ms / 200 ms),读者和竞争更新是独立线程;随机到达时刻和利息写入时刻用固定随机种子',
     '没有验证:真实 Saga 框架(Seata Saga、Temporal 等)对隔离性提供了什么;可交换更新在复杂业务(多字段约束、取消订单要退多种东西)里是否都能做到;“重读值”和“版本检查”这类对策(没有实验);数字里的 50% 取决于我设的窗口与间隔(各 100 ms),不是普遍比例'],
    'Saga 的隔离性')
